DECLARE @product_name VARCHAR(MAX);
DECLARE @list_price   DECIMAL;

DECLARE cursor_product CURSOR
FOR SELECT product_name, list_price
    FROM   production.products;

OPEN cursor_product;

FETCH NEXT FROM cursor_product
INTO @product_name, @list_price;

WHILE @@FETCH_STATUS = 0
BEGIN
    PRINT @product_name + ': $' + CAST(@list_price AS VARCHAR(20));

    FETCH NEXT FROM cursor_product
    INTO @product_name, @list_price;
END;

CLOSE cursor_product;
DEALLOCATE cursor_product;

-- Session 1:
BEGIN TRAN;
UPDATE invoices SET customer_id = 100 WHERE id = 1;
-- (locks invoices, wants invoice_items)
UPDATE invoice_items SET amount = 100 WHERE id = 10;
COMMIT;

-- Session 2:
BEGIN TRAN;
UPDATE invoice_items SET amount = 200 WHERE id = 10;
-- (locks invoice_items, wants invoices)
UPDATE invoices SET total = 500 WHERE id = 1;
COMMIT;
